import logging
import re


class EEVariantGenerator:
    def __init__(self, detailed_bts_info, used_cells):
        self.bts_info = detailed_bts_info['bts_info']
        self.bbmods_info = detailed_bts_info['bbmods_info']
        self.used_cells = set(used_cells)
        self.dn_product_name_mapping = None
        self._all_cells_info = []
        self._passed_cell_dn_type = None
        self._rf_variant = None
        self._smod_variant = None
        self._system_variant = None
        self._mrbts_id = self.bts_info['id']['configuration']

    def prepare_variants_to_report(self):
        used_cell_names = self._get_used_cell_names()
        logging.debug(f'USED_CELL_NAMES: {used_cell_names}')
        device_relations = self._get_device_relations()
        logging.debug(f'DEVICE_RELATIONS: {device_relations}')
        filtered = self._filter_by_used_cells(device_relations, used_cell_names)
        logging.debug(f'FILTERED BY CELL: {filtered}')
        self.dn_product_name_mapping = self.get_dist_name_product_name_mapping()
        logging.debug(f'DIST_NAME_PRODUCT_NAME_MAPPING: {self.dn_product_name_mapping}')
        rf_variant = self._prepare_variant_for_rf_counters(filtered, self.dn_product_name_mapping)
        bbmod_variant = self._prepare_variant_for_bbmod_counters(filtered, self.dn_product_name_mapping)
        smod_variant = self._prepare_variant_for_smod_counters(filtered, self.dn_product_name_mapping)
        system_variant = self._prepare_variant_for_system_counters(filtered, self.dn_product_name_mapping,
                                                                   device_relations)
        logging.debug(f'RF_VARIANT: {rf_variant}')
        logging.debug(f'BBMOD_VARIANT: {bbmod_variant}')
        logging.debug(f'SMOD_VARIANT: {smod_variant}')
        logging.debug(f'SYSTEM_VARIANT: {system_variant}')
        self._rf_variant = rf_variant
        self._bbmod_variant = bbmod_variant
        self._smod_variant = smod_variant
        self._system_variant = system_variant
        return rf_variant, bbmod_variant, smod_variant, system_variant

    @property
    def system_variant(self):
        return self._system_variant

    @property
    def rf_variant(self):
        return self._rf_variant

    @property
    def bbmod_variant(self):
        return self._bbmod_variant

    @property
    def smod_variant(self):
        return self._smod_variant

    @property
    def mrbts_id(self):
        return self._mrbts_id

    @property
    def all_cells_info(self):
        return self._all_cells_info

    def has_bbmod(self):
        return True if self.bts_info['basebandModules'] else False

    def get_all_smods_position(self):
        all_smods = {}
        for smod in self.bts_info['systemModules']:
            all_smods[smod['id']['configuration']] = smod.get('positionInSubrack')  # available only for fullRack
        return all_smods

    def get_ru_cell_relation(self):
        ru_cell = {}
        for rmod_type in self.bts_info['radioModules']:
            for rmod in self.bts_info['radioModules'][rmod_type]:
                key = rmod['id']['configuration']
                all_cells = set()
                for carrier in rmod['carrierList']:
                    cell_dist_name = self._get_device_dist_name(carrier['id']['configuration'])
                    all_cells.add(cell_dist_name)
                ru_cell[key] = all_cells
        return ru_cell

    def get_cable_relation(self):
        devices = {}
        for cable in self.bts_info['cables']:
            first_config_dis_name = cable['firstEndPointId'].get('configuration')
            if first_config_dis_name is None:
                continue
            first_dis_name = self._get_device_dist_name(first_config_dis_name)
            if 'SMOD_EXT' in first_dis_name:
                continue
            if first_dis_name not in devices:
                devices[first_dis_name] = set()

            second_dist_name = self._get_device_dist_name(cable['secondEndPointId']['configuration'])
            devices[first_dis_name].add(second_dist_name)
        return devices

    def get_dist_name_product_name_mapping(self):
        dist_name_product_name = {}
        for rmod_type in self.bts_info['radioModules']:
            for rmod in self.bts_info['radioModules'][rmod_type]:
                dist_name_product_name[rmod['id']['configuration']] = {
                    'product_name': rmod['productName'],
                    'serial_number': rmod['serialNumber']
                }
        for device in self.bts_info['systemModules'] + self.bts_info['basebandModules']:
            product_name = re.split(r'\s+', device['productName'])[0]
            dist_name_product_name[device['id']['configuration']] = {
                'product_name': product_name,
                'serial_number': device['serialNumber']
            }
        for device in self.bts_info.get('fhs', []):
            product_name = re.split(r'\s+', device['productName'])[0]
            dist_name_product_name[device['id']['configuration']] = {
                'product_name': product_name,
                'serial_number': device['serialNumber']
            }
        return dist_name_product_name

    def _get_used_cell_names(self):
        cell_names = set()
        self._passed_cell_dn_type = 'short_name'
        for used_cell in self.used_cells:
            if 'RUNTIME_VIEW' in used_cell:
                self._passed_cell_dn_type = 'runtime'
                break
            elif 'MRBTS' in used_cell and 'RUNTIME_VIEW' not in used_cell:
                self._passed_cell_dn_type = 'configuration'
                break

        for rat in self.bts_info['cells']:
            for cell in self.bts_info['cells'][rat]:
                short_name = cell['id']['configuration'].split(r'/')[-1]
                self._all_cells_info.append(
                    {
                        'runtime': cell['id']['internal'],
                        'configuration': cell['id']['configuration'],
                        'short_name': short_name
                    })
                if self._passed_cell_dn_type == 'runtime':
                    if cell['id']['internal'] in self.used_cells:
                        cell_names.add(short_name)
                if self._passed_cell_dn_type == 'configuration':
                    if cell['id']['configuration'] in self.used_cells:
                        cell_names.add(short_name)

        if self._passed_cell_dn_type == 'short_name':
            cell_names = self.used_cells

        return cell_names

    def _get_device_relations(self):
        all_smods = self.get_all_smods_position()
        cable_relations = self.get_cable_relation()
        ru_cell_relation = self.get_ru_cell_relation()

        device_relations = {
            'rmod_cell': ru_cell_relation,
            'smod': set(all_smods.keys())
        }
        if self.has_bbmod():
            bbmod_ru_relation = self._get_bbmod_ru_relation(cable_relations, ru_cell_relation)
            device_relations['bbmod_ru'] = bbmod_ru_relation
            device_relations['smod_bbmod'] = self._get_smod_bbmod_relation(all_smods)

        return device_relations

    @staticmethod
    def _filter_by_used_cells(device_relations, used_cells):
        filtered = {}

        filtered_ru_cell_relation = {}
        for ru_dist_name in device_relations['rmod_cell']:
            for cell_dist_name in device_relations['rmod_cell'][ru_dist_name]:
                for used_cell in used_cells:
                    if cell_dist_name.endswith(used_cell):
                        if ru_dist_name not in filtered_ru_cell_relation:
                            filtered_ru_cell_relation[ru_dist_name] = set()
                        filtered_ru_cell_relation[ru_dist_name].add(used_cell)
        filtered['rmod_cell'] = filtered_ru_cell_relation

        if 'bbmod_ru' in device_relations:
            filtered_bbmod_ru_relation = {}
            for bbmod_dist_name in device_relations['bbmod_ru']:
                for ru_dist_name in device_relations['bbmod_ru'][bbmod_dist_name]:
                    for used_ru_dist_name in filtered_ru_cell_relation:
                        if used_ru_dist_name == ru_dist_name:
                            if bbmod_dist_name not in filtered_bbmod_ru_relation:
                                filtered_bbmod_ru_relation[bbmod_dist_name] = set()
                            filtered_bbmod_ru_relation[bbmod_dist_name].add(used_ru_dist_name)
            filtered['bbmod_ru'] = filtered_bbmod_ru_relation
            filtered['smod_bbmod'] = device_relations['smod_bbmod']

        filtered['smod'] = device_relations['smod']

        return filtered

    def _get_smod_bbmod_relation(self, smods):
        smod_bbmod_relation = {}
        for smod_dn in smods:
            smod_position = smods[smod_dn]
            smod_bbmod_relation[smod_dn] = set()
            if smod_position:
                smod_horizontal_position = 1 if 'left' in smod_position.lower() else 2

            for bbmod_dn in self.bbmods_info:
                if (smod_position is None
                        or int(self.bbmods_info[bbmod_dn]['horizontalPosition']) == smod_horizontal_position):
                    smod_bbmod_relation[smod_dn].add(bbmod_dn)
        return smod_bbmod_relation

    @staticmethod
    def _get_bbmod_ru_relation(cable_relations, ru_cell_relation):
        bbmod_ru_relation = {}
        chained_rus = {}
        for firstpoint in cable_relations:
            for ru_dist_name in ru_cell_relation:
                if ru_dist_name in cable_relations[firstpoint]:
                    if firstpoint not in bbmod_ru_relation:
                        bbmod_ru_relation[firstpoint] = set()
                    bbmod_ru_relation[firstpoint].add(ru_dist_name)

        for dist_name in bbmod_ru_relation:
            if 'RMOD' in dist_name:
                chained_rus[dist_name] = bbmod_ru_relation[dist_name]

        for dist_name in chained_rus:
            del bbmod_ru_relation[dist_name]

        chained_rus_copy = chained_rus.copy()
        while chained_rus_copy:
            for bbmod in bbmod_ru_relation:
                for ru in chained_rus:
                    if ru in chained_rus_copy and ru in bbmod_ru_relation[bbmod]:
                        bbmod_ru_relation[bbmod].update(chained_rus[ru])
                        del chained_rus_copy[ru]

        # Assign RMODs under FHS to the BBMOD connected to this FHS (BBMOD <-> FHS <-> RMODs)
        for fhs_dn in list(bbmod_ru_relation):
            if 'FHS' not in fhs_dn:
                continue
            rus_under_fhs = bbmod_ru_relation[fhs_dn]
            bbmod_dn = None
            for firstpoint in cable_relations:
                if 'BBMOD' in firstpoint and fhs_dn in cable_relations[firstpoint]:
                    bbmod_dn = firstpoint
                    break
            if bbmod_dn is not None:
                if bbmod_dn not in bbmod_ru_relation:
                    bbmod_ru_relation[bbmod_dn] = set()
                bbmod_ru_relation[bbmod_dn].update(rus_under_fhs)
                del bbmod_ru_relation[fhs_dn]

        return bbmod_ru_relation

    def _prepare_variant_for_rf_counters(self, filtered, mapping):
        def filter_by_used_rmod(bbmod_ru_relation, rmod_dist_name):
            used_bmods = set()
            for bbmod_dist_name in bbmod_ru_relation:
                if rmod_dist_name in bbmod_ru_relation[bbmod_dist_name]:
                    used_bmods.add(bbmod_dist_name)
            return used_bmods

        variant_per_ru = {}
        for ru_dist_name in filtered['rmod_cell']:
            variant_per_ru[ru_dist_name] = {
                'cell': sorted(filtered['rmod_cell'][ru_dist_name]),
                'rmod': sorted([mapping[ru_dist_name]['product_name']]),
                'rmod_objects': [ru_dist_name.split('/')[-1]],
                'smod': sorted([mapping[smod_dist_name]['product_name']for smod_dist_name in filtered['smod']]),
                'smod_objects': sorted([smod_dist_name.split('/')[-1] for smod_dist_name in filtered['smod']]),
                'mrbts_id': self.mrbts_id,
                'object': ru_dist_name.split('/')[-1],
                'serial_number': mapping[ru_dist_name]['serial_number']
            }

            if 'bbmod_ru' in filtered:
                used_bbmods = filter_by_used_rmod(filtered['bbmod_ru'], ru_dist_name)
                variant_per_ru[ru_dist_name]['bbmod'] = sorted([mapping[bbmod_dist_name]['product_name'] for
                                                                bbmod_dist_name in used_bbmods])
                variant_per_ru[ru_dist_name]['bbmod_objects'] = sorted([bbmod_dist_name.split('/')[-1] for
                                                                        bbmod_dist_name in used_bbmods])
        return variant_per_ru

    def _prepare_variant_for_bbmod_counters(self, filtered, mapping):
        variant_per_bbmod = {}
        for bbmod_dist_name in filtered.get('bbmod_ru', {}):
            all_cell_under_bbmod = {cell for r_dn in filtered['bbmod_ru'][bbmod_dist_name] for cell in
                                    filtered['rmod_cell'][r_dn]}
            variant_per_bbmod[bbmod_dist_name] = {
                'cell': sorted(all_cell_under_bbmod),
                'rmod': sorted([mapping[r_dn]['product_name'] for r_dn in filtered['bbmod_ru'][bbmod_dist_name]]),
                'rmod_objects': sorted([r_dn.split('/')[-1] for r_dn in filtered['bbmod_ru'][bbmod_dist_name]]),
                'bbmod': sorted([mapping[bbmod_dist_name]['product_name']]),
                'bbmod_objects': [bbmod_dist_name.split('/')[-1]],
                'smod': sorted([mapping[smod_dist_name]['product_name'] for smod_dist_name in filtered['smod']]),
                'smod_objects': sorted([smod_dist_name.split('/')[-1] for smod_dist_name in filtered['smod']]),
                'mrbts_id': self.mrbts_id,
                'object': bbmod_dist_name.split('/')[-1],
                'serial_number': mapping[bbmod_dist_name]['serial_number']
            }

        return variant_per_bbmod

    def _prepare_variant_for_smod_counters(self, filtered, mapping):
        variant_per_smod = {}
        for smod_dist_name in filtered['smod']:
            variant_per_smod[smod_dist_name] = {
                'cell': sorted({cell for r_dn in filtered['rmod_cell'] for cell in filtered['rmod_cell'][r_dn]}),
                'rmod': sorted([mapping[rmod_dist_name]['product_name'] for rmod_dist_name in filtered['rmod_cell']]),
                'rmod_objects': sorted([rmod_dist_name.split('/')[-1] for rmod_dist_name in filtered['rmod_cell']]),
                'smod': sorted([mapping[smod_dist_name]['product_name']]),
                'smod_objects': [smod_dist_name.split('/')[-1]],
                'mrbts_id': self.mrbts_id,
                'object': smod_dist_name.split('/')[-1],
                'serial_number': mapping[smod_dist_name]['serial_number']
            }
            if 'bbmod_ru' in filtered:
                variant_per_smod[smod_dist_name]['bbmod'] = sorted([mapping[b_dn]['product_name'] for
                                                                    b_dn in filtered['smod_bbmod'][smod_dist_name]])
                variant_per_smod[smod_dist_name]['bbmod_objects'] = sorted(
                    [b_dn.split('/')[-1] for b_dn in filtered['smod_bbmod'][smod_dist_name]])
        return variant_per_smod

    def _prepare_variant_for_system_counters(self, filtered, mapping, device_relations):
        dev_rel = device_relations
        system_variant = {
            self.mrbts_id: {
                'cell': sorted({cell for r_dn in filtered['rmod_cell'] for cell in filtered['rmod_cell'][r_dn]}),
                'rmod': sorted([mapping[r_dn]['product_name'] for r_dn in dev_rel['rmod_cell']]),
                'rmod_objects': sorted([r_dn.split('/')[-1] for r_dn in dev_rel['rmod_cell']]),
                'smod': sorted([mapping[smod_dist_name]['product_name'] for smod_dist_name in dev_rel['smod']]),
                'smod_objects': sorted([smod_dist_name.split('/')[-1] for smod_dist_name in dev_rel['smod']]),
                'mrbts_id': self.mrbts_id,
                'object': self.mrbts_id
            }
        }
        if 'bbmod_ru' in dev_rel:
            system_variant[self.mrbts_id]['bbmod'] = sorted([mapping[b_dn]['product_name']
                                                             for s_dn in dev_rel['smod_bbmod']
                                                             for b_dn in dev_rel['smod_bbmod'][s_dn]])
            system_variant[self.mrbts_id]['bbmod_objects'] = sorted([b_dn.split('/')[-1]
                                                                     for s_dn in dev_rel['smod_bbmod']
                                                                     for b_dn in dev_rel['smod_bbmod'][s_dn]])
        return system_variant

    @staticmethod
    def _get_device_dist_name(port_dist_name):
        split_dist_name = port_dist_name.split(r'/')
        del split_dist_name[-1]
        return '/'.join(split_dist_name)
